# CDC Travel Health Information
import requests

CDC_TRAVEL_API_KEY = "f430db9fcdba51ae39fd533b19a6a44e"
BASE_URL = "https://wwwnc.cdc.gov/travel/api/v1"

def get_destination_health(destination_country):
    """Get health recommendations for travel destination"""
    response = requests.get(
        f"{BASE_URL}/destinations/{destination_country}",
        params={"api_key": CDC_TRAVEL_API_KEY}
    )
    return response.json()

def get_required_vaccinations(destination):
    """Get required vaccinations for destination"""
    response = requests.get(
        f"{BASE_URL}/vaccinations/required",
        params={
            "destination": destination,
            "api_key": CDC_TRAVEL_API_KEY
        }
    )
    return response.json()
